def solve(matrix):
    """Return the determinant of a square integer matrix, computed exactly
    with rational Gaussian elimination. An empty matrix has determinant 1."""
    n = len(matrix)
    if n == 0:
        return 1
    if any(len(row) != n for row in matrix):
        raise ValueError("matrix must be square")
    if n == 1 and len(matrix[0]) == 0:
        return 1
    rows = [[Fraction(x) for x in row] for row in matrix]
    det = Fraction(1)
    for k in range(n):
        if rows[k][k] == 0:
            for i in range(k + 1, n):
                if rows[i][k] != 0:
                    rows[k], rows[i] = rows[i], rows[k]
                    det = -det
                    break
            else:
                return 0
        pivot = rows[k][k]
        det *= pivot
        for i in range(k + 1, n):
            f = rows[i][k] / pivot
            if f:
                for j in range(k, n):
                    rows[i][j] -= f * rows[k][j]
    return int(det)
