            swap_row = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            sign = -sign
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Compute the fraction‑free update
                A[i][j] = A[i][j] * A[k][k] - A[i][k] * A[k][j]
                if k > 0:
