def solve(matrix):
    """Return determinant of an integer square matrix.
    Uses the fraction‑free Bareiss algorithm (O(n³)).
    Empty matrix (0×0) is defined to have determinant 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    A = [list(row) for row in matrix]
    sign = 1
    for k in range(n-1):
        # Ensure pivot is non‑zero; if zero, swap with a lower row.
        if A[k][k] == 0:
            swap = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            A[k], A[swap] = A[swap], A[k]
            sign = -sign
        for i in range(k+1, n):
            for j in range(k+1, n):
                A[i][j] = A[i][j] * A[k][k] - A[i][k] * A[k][j]
                if k > 0:
                    A[i][j] //= A[k-1][k-1]
        for i in range(k+1, n):
            A[i][k] = 0
    return sign * A[n-1][n-1]

