def solve(path):
    """Simplify an absolute Unix path.
    Collapse '.' and '..' components, remove duplicate slashes, and ensure
    the result starts with '/' and has no trailing slash (except for the root).
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

