def solve(coins, amount):
    """Return the fewest number of coins (unlimited supply of each value in
    `coins`) that sum to `amount`, or -1 if impossible."""
    INF = amount + 1
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if 0 < c <= a:
                prev = dp[a - c] + 1
                if prev < best:
                    best = prev
        dp[a] = best
    return dp[amount] if dp[amount] <= amount else -1

