def solve(path: str) -> str:
    """Simplify an absolute Unix path.
    Handles '.' and '..', collapses multiple slashes, and removes trailing slash
    except for the root.
    """
    # Defensive: ensure we have a string
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    # Remove surrounding whitespace
    path = path.strip()
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            stack.append(part)
